    stakesStories: [{"strong": "Merece el minuto extra:", "rest": "En Luxemburgo, clasificar mal los residuos se multa con 25–250 €, y un contenedor contaminado se factura al titular de la cuenta — normalmente el casero, no un inquilino concreto."}, {"strong": "Acláralo antes:", "rest": "Un frasco grasiento o un envase sin lavar en la bolsa Valorlux puede hacer que se rechace toda la bolsa en la planta de clasificación y acabe en el vertedero en vez de reciclarse."}, {"strong": "Sin excepciones:", "rest": "Las pilas y las bombillas nunca van a un contenedor de la calle, por pequeñas que sean — siempre se llevan al Centro de Recursos."}, {"strong": "Sobre todo en verano:", "rest": "Un contenedor de biorresiduos que pasa demasiado tiempo entre recogidas atrae moscas y plagas enseguida — un buen aclarado entre recogidas ayuda mucho."}, {"strong": "Solo botellas y frascos:", "rest": "La cerámica y el vidrio de ventana se funden a una temperatura distinta que el vidrio de botella y pueden arruinar todo un lote de vidrio reciclado."}, {"strong": "Átala, no la rellenes a presión:", "rest": "Una bolsa Valorlux demasiado llena o rota suele quedarse en la acera sin recoger — el equipo no se lleva lo que ya se está saliendo."}, {"strong": "Mantenlo seco:", "rest": "El cartón tiene que estar seco para reciclarse — una mañana de lluvia en la acera puede convertir toda una pila en pulpa."}, {"strong": "Los festivos cambian el calendario:", "rest": "Un día festivo normalmente retrasa la recogida un día en vez de suprimirla — mira el calendario de arriba antes de dar por hecho que no pasan."}],
