    stakesStories: [{"strong": "Ça vaut la minute en plus :", "rest": "Au Luxembourg, un tri mal fait est puni d'une amende de 25 à 250 €, et une poubelle contaminée est facturée au prix coûtant au titulaire du compte — en général le propriétaire, pas un locataire en particulier."}, {"strong": "Rince-le d'abord :", "rest": "Un seul bocal gras ou une barquette sale dans le sac Valorlux peut faire refuser tout le sac au tri et l'envoyer à la décharge au lieu du recyclage."}, {"strong": "Aucune exception :", "rest": "Les piles et les ampoules ne vont jamais dans une poubelle de rue, même petites — c'est toujours un dépôt au Centre de ressources."}, {"strong": "Surtout en été :", "rest": "Une poubelle de biodéchets laissée trop longtemps entre deux collectes attire vite mouches et nuisibles — un petit coup de rinçage entre les passages aide beaucoup."}, {"strong": "Bouteilles et bocaux uniquement :", "rest": "La céramique et le verre à vitre fondent à une autre température que le verre des bouteilles et peuvent gâcher tout un lot de verre recyclé."}, {"strong": "Noue-le, ne le bourre pas :", "rest": "Un sac Valorlux trop plein ou déchiré reste souvent au bord du trottoir sans être ramassé — l'équipe ne prend pas ce qui déborde déjà."}, {"strong": "Garde-le au sec :", "rest": "Le carton doit être sec pour être recyclé — une matinée de pluie sur le trottoir peut transformer toute une pile en bouillie."}, {"strong": "Les jours fériés décalent le calendrier :", "rest": "Un jour férié décale en général la collecte d'un jour au lieu de la supprimer — regarde le calendrier ci-dessus avant de croire qu'il n'y a pas de passage."}],
