    // Added 2026-10-17: strings that were missing (they used to fall back to English).
    stakesStories: [{"strong": "Минута того стоит:", "rest": "В Люксембурге за неправильную сортировку штрафуют на 25–250 €, а загрязнённый контейнер выставляют по себестоимости тому, на кого оформлен договор — обычно хозяину жилья, а не конкретному жильцу."}, {"strong": "Сначала сполосните:", "rest": "Одна жирная банка или невымытый контейнер в мешке Valorlux — и весь мешок могут отбраковать на сортировке и отправить на свалку вместо переработки."}, {"strong": "Без исключений:", "rest": "Батарейки и лампочки никогда не выбрасывают в уличный контейнер, даже самые маленькие — их всегда сдают в Centre des Ressources."}, {"strong": "Особенно летом:", "rest": "Если контейнер с биоотходами слишком долго стоит между вывозами, быстро появляются мухи и вредители — короткая промывка между вывозами сильно помогает."}, {"strong": "Только бутылки и банки:", "rest": "Керамика и оконное стекло плавятся при другой температуре, чем стеклотара, и могут испортить целую партию переработанного стекла."}, {"strong": "Завяжите, а не утрамбуйте:", "rest": "Переполненный или порванный мешок Valorlux часто остаётся на обочине — бригада не берёт то, что уже вываливается."}, {"strong": "Держите сухим:", "rest": "Картон для переработки должен быть сухим — одно дождливое утро на обочине может превратить всю стопку в кашу."}, {"strong": "Праздники сдвигают расписание:", "rest": "Из-за праздника вывоз обычно переносят на день, а не отменяют — загляните в календарь выше, прежде чем решать, что вывоза нет."}],
