    stakesStories: [{"strong": "Déi Extra-Minutt ass et wäert:", "rest": "zu Lëtzebuerg gëtt falsch sortéierten Offall mat €25–250 bestrooft, a eng verschmotzt Poubelle gëtt dem Kontoinhaber zum Käschtepräis a Rechnung gestallt — meeschtens dem Proprietaire, net engem eenzelnen Locataire."}, {"strong": "Fir d'éischt ofspullen:", "rest": "Ee fettegt Glas oder eng ongewäsch Schossel am Valorlux-Sak kann dozou féieren, datt de ganze Sak beim Sortéieren ofgelehnt gëtt an op der Deponie landt amplaz recycléiert ze ginn."}, {"strong": "Keng Ausnamen:", "rest": "Batterien a Luuchten kommen ni an eng Poubelle um Trottoir, egal wéi kleng — si ginn ëmmer am Centre des Ressources ofgeliwwert."}, {"strong": "Besonnesch am Summer:", "rest": "Eng Bio-Poubelle, déi ze laang tëscht zwou Kollekte bleift, zitt séier Mécken a Schädlinge un — kuerz ofspullen tëscht den Ofhuelen hëlleft vill."}, {"strong": "Nëmmen Fläschen a Glieser:", "rest": "Keramik a Fënsterglas schmëlzen bei enger anerer Temperatur wéi Fläscheglas a kënnen eng ganz Charge recycléiert Glas ruinéieren."}, {"strong": "Zebannen, net stopfen:", "rest": "E iwwerfëllte oder gerappte Valorlux-Sak bleift dacks um Trottoir leien — d'Equipe hëlt net mat, wat schonn erausfällt."}, {"strong": "Dréchen halen:", "rest": "Kartong muss dréchen sinn fir recycléiert ze ginn — ee reenegen Moien um Trottoir kann e ganze Stapel zu Brei maachen."}, {"strong": "Feierdeeg verréckele de Kalenner:", "rest": "E Feierdag verréckelt d'Kollekt normalerweis em een Dag amplaz se ausfalen ze loossen — kuck am Kalenner uewendriwwer, ier du denks, et gëtt keng Ofhuelung."}],
