    // Added 2026-10-17: strings that were missing (they used to fall back to English).
    stakesStories: [{"strong": "ひと手間かける価値あり:", "rest": "ルクセンブルクでは分別違反に25〜250ユーロの罰金があり、汚染されたゴミ箱は契約者（たいていは入居者個人ではなく大家さん）に実費で請求されます。"}, {"strong": "先にすすいで:", "rest": "油っぽい瓶や洗っていない容器がひとつでもValorluxの袋に入っていると、袋ごと選別で弾かれ、リサイクルされずに埋め立てられることがあります。"}, {"strong": "例外なし:", "rest": "電池や電球は、どんなに小さくても道端のゴミ箱には出せません ― 必ず資源センターへ持ち込みます。"}, {"strong": "特に夏は:", "rest": "生ゴミ用の箱を収集の合間に放置すると、すぐにハエや害虫が寄ってきます ― 収集の合間にさっとすすぐだけでも効果的です。"}, {"strong": "出せるのは瓶だけ:", "rest": "陶器や板ガラスは瓶のガラスと溶ける温度が違うため、再生ガラスのロット全体をダメにしてしまうことがあります。"}, {"strong": "詰め込まずに結ぶ:", "rest": "いっぱいに詰めた袋や破れたValorluxの袋は、回収されずに道端に残されがちです ― 作業員はあふれかけたものは持っていってくれません。"}, {"strong": "濡らさないで:", "rest": "段ボールはリサイクルするために乾いている必要があります ― 雨の朝に出しっぱなしにすると、山積みが丸ごとドロドロになることも。"}, {"strong": "祝日は日程がずれます:", "rest": "祝日は収集がなくなるのではなく、たいてい1日ずれるだけです ― 収集がないと決めつける前に、上のカレンダーを確認してください。"}],
