  stakesStories: [{"strong": "ایک منٹ مزید لگانا فائدہ مند ہے:", "rest": "لکسمبرگ میں غلط طریقے سے چھانٹے گئے کچرے پر €25–250 جرمانہ ہوتا ہے، اور آلودہ ڈبے کا خرچ اکاؤنٹ ہولڈر کو دینا پڑتا ہے — عموماً مکان مالک کو، کسی ایک کرایہ دار کو نہیں۔"}, {"strong": "پہلے دھو لیں:", "rest": "Valorlux کے تھیلے میں ایک چکنا مرتبان یا بغیر دھوئی ڈبیا پورے تھیلے کو چھانٹی کے دوران مسترد کروا سکتی ہے، اور وہ ری سائیکل ہونے کے بجائے کچرا گھر بھیج دیا جاتا ہے۔"}, {"strong": "کوئی استثنا نہیں:", "rest": "بیٹریاں اور بلب کبھی سڑک کنارے کے ڈبے میں نہیں جاتے، چاہے کتنے ہی چھوٹے ہوں — انہیں ہمیشہ ریسورس سینٹر میں جمع کرانا ہوتا ہے۔"}, {"strong": "خاص طور پر گرمیوں میں:", "rest": "نامیاتی کچرے کا ڈبہ جمع آوری کے درمیان بہت دیر پڑا رہے تو مکھیاں اور کیڑے جلد آ جاتے ہیں — ہر پک اپ کے بیچ ایک جلدی کی دھلائی بہت کام آتی ہے۔"}, {"strong": "صرف بوتلیں اور مرتبان:", "rest": "چینی مٹی کے برتن اور کھڑکی کا شیشہ بوتل کے شیشے سے مختلف درجہ حرارت پر پگھلتے ہیں اور ری سائیکل شدہ شیشے کی پوری کھیپ خراب کر سکتے ہیں۔"}, {"strong": "باندھیں، ٹھونسیں نہیں:", "rest": "حد سے زیادہ بھرا یا پھٹا ہوا Valorlux تھیلا اکثر سڑک کنارے ہی چھوڑ دیا جاتا ہے — عملہ وہ چیز نہیں اٹھاتا جو پہلے ہی باہر گر رہی ہو۔"}, {"strong": "خشک رکھیں:", "rest": "گتے کو ری سائیکل ہونے کے لیے خشک ہونا چاہیے — سڑک کنارے پڑی ایک بارش والی صبح پورے ڈھیر کو گودا بنا سکتی ہے۔"}, {"strong": "چھٹیوں سے شیڈول بدل جاتا ہے:", "rest": "سرکاری چھٹی عموماً جمع آوری کو چھوڑنے کے بجائے ایک دن آگے کر دیتی ہے — یہ فرض کرنے سے پہلے کہ پک اپ نہیں ہے، اوپر کیلنڈر دیکھ لیں۔"}],
